def transform(grid):
    # crop background, retain clean principal rectangles (demonstrations show noise removed,
    # and stray pixels within colored rectangles restored from majority color).
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    # Identify large solid same-color rectangle-like clusters, tolerating noise colors.
    seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); pts=[]
        while stack:
          y,x=stack.pop(); pts.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
              seen.add((a,b)); stack.append((a,b))
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        t,b=min(ys),max(ys); l,rr=min(xs),max(xs)
        box=(b-t+1)*(rr-l+1)
        if box>=4 and len(pts)/box>=.55 and b>t and rr>l:
          for y in range(t,b+1):
            for x in range(l,rr+1): out[y][x]=col
    return out

