    # color that lie inside a rectangular frame of a different color.
    # Demos show the upper-left frame: 4-filled rectangle, 1 frame, and
    # interior 4s are recolored 1; isolated 4s outside remain unchanged.
    h, w = len(grid), len(grid[0])
