            continue
        r0,c0 = cells[0]
        # locate a rectangular outline of this singleton's color enclosing
        # an object of another color; choose smallest enclosing rectangle.
        for frame in set(v for row in grid for v in row):
            if frame == color: continue
            for top in range(h):
                for bottom in range(top+2,h):
                    for left in range(w):
                        for right in range(left+2,w):
                            if not (top <= r0 <= bottom and left <= c0 <= right):
                                continue
                            boundary = all(grid[top][c] == frame and grid[bottom][c] == frame for c in range(left,right+1)) and all(grid[r][left] == frame and grid[r][right] == frame for r in range(top,bottom+1))
                            if not boundary: continue
                            # marker singleton must be elsewhere, and recolor interior object
                            for r in range(top+1,bottom):
                                for c in range(left+1,right):
                                    if grid[r][c] == frame:
                                        out[r][c] = color

    # Directly infer frame/palette from test: singleton 4 at upper right;
