import random
from collections import Counter

def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [[0] * (2*m) for _ in range(2*n)]
    for r in range(n):
        out[r][:m] = grid[r][:]
    counts = Counter(x for row in grid for x in row)
    colors = sorted(counts)
    weights = [counts[c] for c in colors]
    rng = random.Random(sum((r+1)*(c+3)*v for r,row in enumerate(grid) for c,v in enumerate(row)))
    for r in range(2*n):
        for c in range(2*m):
            if r >= n or c >= m:
                out[r][c] = rng.choices(colors, weights=weights, k=1)[0]
    return out

